          ),
    );
  } catch {
    results.push(
      result(
        "VIR-DEPS-002",
        "fail",
        "Cannot read the frontend manifest or Vireo compatibility contract",
        "Restore frontend/package.json and contracts/vireo-package-compatibility.json.",
      ),
    );
