    const datasourceProblem = externalDatasourceProblem();
    results.push(
      datasourceProblem
        ? result(
            "VIR-DB-001",
            "fail",
            datasourceProblem,
            "Export the complete SPRING_DATASOURCE_URL, SPRING_DATASOURCE_USERNAME, and SPRING_DATASOURCE_PASSWORD configuration.",
